 const atomicDesign = "{\"parsed\":{\"_path\":\"/atomic-design\",\"_dir\":\"\",\"_draft\":false,\"_partial\":false,\"_locale\":\"\",\"title\":\"Atomic Design\",\"description\":\"\",\"options\":[{\"label\":\"Basic\",\"price\":10,\"data\":1000},{\"label\":\"Premium\",\"price\":50,\"data\":5000}],\"body\":{\"type\":\"root\",\"children\":[{\"type\":\"element\",\"tag\":\"div\",\"props\":{\"style\":\"minHeight: 288px\",\"className\":[\"min-h-72\",\"bg-transparent\"]},\"children\":[{\"type\":\"element\",\"tag\":\"p\",\"props\":{},\"children\":[{\"type\":\"element\",\"tag\":\"img\",\"props\":{\"alt\":\"atomic design overview\",\"src\":\"atomic-design-abstract-concrete.png\",\"title\":\"abstract to concrete\"},\"children\":[]},{\"type\":\"element\",\"tag\":\"em\",\"props\":{},\"children\":[{\"type\":\"text\",\"value\":\"Atomic Design - Brad Frost\"}]}]}]},{\"type\":\"element\",\"tag\":\"p\",\"props\":{},\"children\":[{\"type\":\"text\",\"value\":\"This article is based on the work of \"},{\"type\":\"element\",\"tag\":\"a\",\"props\":{\"href\":\"https://atomicdesign.bradfrost.com/\",\"rel\":[\"nofollow\"]},\"children\":[{\"type\":\"text\",\"value\":\"Brad Frost\"}]},{\"type\":\"text\",\"value\":\". You'll find more detailled insights and helpful examples in his \"},{\"type\":\"element\",\"tag\":\"a\",\"props\":{\"href\":\"https://atomicdesign.bradfrost.com/\",\"rel\":[\"nofollow\"]},\"children\":[{\"type\":\"text\",\"value\":\"book\"}]},{\"type\":\"text\",\"value\":\".\"}]},{\"type\":\"element\",\"tag\":\"h3\",\"props\":{\"id\":\"atoms\"},\"children\":[{\"type\":\"text\",\"value\":\"Atoms\"}]},{\"type\":\"element\",\"tag\":\"p\",\"props\":{},\"children\":[{\"type\":\"text\",\"value\":\"Atoms are the very basic building blocks of a Design System. They cannot be divided into smaller blocks. In the context of Web Development, Atoms are basically the same as the available HTML tags, but can also be extended by e.g. Icon.\"}]},{\"type\":\"element\",\"tag\":\"div\",\"props\":{\"className\":[\"bg-gray-100\",\"rounded-lg\",\"p-4\",\"grid\",\"gap-4\",\"grid-cols-1\",\"sm:grid-cols-2\",\"grid-flow-row\"]},\"children\":[{\"type\":\"element\",\"tag\":\"my-button\",\"props\":{},\"children\":[{\"type\":\"text\",\"value\":\"button\"}]},{\"type\":\"element\",\"tag\":\"my-button\",\"props\":{\"type\":\"secondary\"},\"children\":[{\"type\":\"text\",\"value\":\"button\"}]},{\"type\":\"element\",\"tag\":\"text-field\",\"props\":{\"placeholder\":\"Password\",\"type\":\"password\"},\"children\":[{\"type\":\"text\",\"value\":\"hello\"}]},{\"type\":\"element\",\"tag\":\"text-field\",\"props\":{\"placeholder\":\"123\",\"type\":\"number\"},\"children\":[]},{\"type\":\"element\",\"tag\":\"toggle\",\"props\":{},\"children\":[]}]},{\"type\":\"element\",\"tag\":\"h3\",\"props\":{\"id\":\"molecules\"},\"children\":[{\"type\":\"text\",\"value\":\"Molecules\"}]},{\"type\":\"element\",\"tag\":\"p\",\"props\":{},\"children\":[{\"type\":\"text\",\"value\":\"Multiple Atoms can be used to form Molecules. They form the fundamental elements in the Design that serve a certain purpose. For example a Button and an InputField can form a Searchbox.\"}]},{\"type\":\"element\",\"tag\":\"div\",\"props\":{\"className\":[\"bg-gray-100\",\"rounded-lg\",\"p-4\",\"grid\",\"gap-4\",\"grid-cols-1\",\"lg:grid-cols-2\",\"grid-flow-row\"]},\"children\":[{\"type\":\"text\",\"value\":\"\\n  \"},{\"type\":\"element\",\"tag\":\"search-field\",\"props\":{},\"children\":[]},{\"type\":\"text\",\"value\":\"\\n  \"},{\"type\":\"element\",\"tag\":\"card\",\"props\":{\"className\":[\"h-12\",\"lg:h-24\"],\"link\":\"\"},\"children\":[{\"type\":\"text\",\"value\":\"Some clickable Card\"}]}]},{\"type\":\"element\",\"tag\":\"h3\",\"props\":{\"id\":\"organisms\"},\"children\":[{\"type\":\"text\",\"value\":\"Organisms\"}]},{\"type\":\"element\",\"tag\":\"p\",\"props\":{},\"children\":[{\"type\":\"text\",\"value\":\"Organisms are groups of Molecules and provide more complex and distinct parts of the UI. Organisms can also contain Atoms or other Organisms. You can think of a page Navigation containing a Logo, Links, Buttons and a Searchbox.\"}]},{\"type\":\"element\",\"tag\":\"div\",\"props\":{\"className\":[\"bg-gray-100\",\"p-4\",\"rounded-lg\"]},\"children\":[{\"type\":\"element\",\"tag\":\"signup-form\",\"props\":{\":options\":\"options\"},\"children\":[]}]},{\"type\":\"element\",\"tag\":\"h3\",\"props\":{\"id\":\"beyond-chemistry\"},\"children\":[{\"type\":\"text\",\"value\":\"Beyond Chemistry\"}]},{\"type\":\"element\",\"tag\":\"h4\",\"props\":{\"id\":\"templates\"},\"children\":[{\"type\":\"text\",\"value\":\"Templates\"}]},{\"type\":\"element\",\"tag\":\"p\",\"props\":{},\"children\":[{\"type\":\"text\",\"value\":\"One step further, the chemistry analogy ends and another step towards a final Page comes into play. Templates are basically layout definitions, similar to Wireframes, that define how a page should be structured from a high-level view. Templates do not have any content and therefore focus on the skeleton of building blocks and how they can be combined and arranged.\"}]},{\"type\":\"element\",\"tag\":\"h4\",\"props\":{\"id\":\"pages\"},\"children\":[{\"type\":\"text\",\"value\":\"Pages\"}]},{\"type\":\"element\",\"tag\":\"p\",\"props\":{},\"children\":[{\"type\":\"text\",\"value\":\"Pages are concrete instances of templates and therefore filled with content. While Templates are content agnostic and do not represent any branding or design language, two pages can have quite different look & feel based on the content. Imagine two E-Commerce pages sharing a common Design System and template. One of them sells coffee beans, the other offers dog food. Despite the common ground the both will have distinct appearances due to the context and the choice of content, colors, fonts, images, language etc.\"}]},{\"type\":\"element\",\"tag\":\"p\",\"props\":{},\"children\":[{\"type\":\"text\",\"value\":\"Further, Pages can present variations and combinations of elements of the Design System:\"}]},{\"type\":\"element\",\"tag\":\"ul\",\"props\":{},\"children\":[{\"type\":\"element\",\"tag\":\"li\",\"props\":{},\"children\":[{\"type\":\"text\",\"value\":\"headlines and other content might be longer/shorter than expected\"}]},{\"type\":\"element\",\"tag\":\"li\",\"props\":{},\"children\":[{\"type\":\"text\",\"value\":\"content in different languages can have big impact on the resulting layout\"}]},{\"type\":\"element\",\"tag\":\"li\",\"props\":{},\"children\":[{\"type\":\"text\",\"value\":\"empty shopping cart vs. filled shopping cart\"}]},{\"type\":\"element\",\"tag\":\"li\",\"props\":{},\"children\":[{\"type\":\"text\",\"value\":\"users with different roles and permissions\"}]},{\"type\":\"element\",\"tag\":\"li\",\"props\":{},\"children\":[{\"type\":\"text\",\"value\":\"first-time users vs. regular users\"}]}]},{\"type\":\"element\",\"tag\":\"h3\",\"props\":{\"id\":\"resources\"},\"children\":[{\"type\":\"text\",\"value\":\"Resources\"}]},{\"type\":\"element\",\"tag\":\"ul\",\"props\":{},\"children\":[{\"type\":\"element\",\"tag\":\"li\",\"props\":{},\"children\":[{\"type\":\"element\",\"tag\":\"a\",\"props\":{\"href\":\"https://atomicdesign.bradfrost.com/table-of-contents/\",\"rel\":[\"nofollow\"]},\"children\":[{\"type\":\"text\",\"value\":\"Atomic Design by Brad Frost\"}]}]}]}],\"toc\":{\"title\":\"\",\"searchDepth\":2,\"depth\":2,\"links\":[{\"id\":\"atoms\",\"depth\":3,\"text\":\"Atoms\"},{\"id\":\"molecules\",\"depth\":3,\"text\":\"Molecules\"},{\"id\":\"organisms\",\"depth\":3,\"text\":\"Organisms\"},{\"id\":\"beyond-chemistry\",\"depth\":3,\"text\":\"Beyond Chemistry\"},{\"id\":\"resources\",\"depth\":3,\"text\":\"Resources\"}]}},\"_type\":\"markdown\",\"_id\":\"content:atomic-design.md\",\"_source\":\"content\",\"_file\":\"atomic-design.md\",\"_stem\":\"atomic-design\",\"_extension\":\"md\"},\"hash\":\"z5wRPfJwiO\"}";

